package org.thortracker.model

import kotlin.test.Test
import kotlin.math.abs
import kotlin.test.assertEquals
import kotlin.test.assertTrue
import org.thortracker.backend.UgeExporter

/**
 * Runs on every core target (JVM for Android, linuxX64 for the Deck). Expected values were produced on the JVM:
 * number text by java.util.Formatter (String.format(Locale.ROOT, ...)), .scl cents and .uge bytes by the JVM build of
 * this core, which CI checks byte for byte against examples/thor-groove.uge. Native must give the same results.
 */
class CrossPlatformGoldenTest {
    @Test fun numberTextMatchesJavaFormatter() {
        for ((bits, mode, expected) in NUMBERS) {
            val value = Double.fromBits(bits)
            val text = NumberText.fixed(value, mode.take(1).toInt(), plus = mode.endsWith("+"))
            assertEquals(expected, text, "fixed($value, $mode)")
        }
    }

    /**
     * Cents from ratios go through log2, whose last bit differs between the JVM and native libm (seen: up to ~1e-13
     * cents on just-5-limit), so cents compare within 1e-9. What users get, the note and 40y bend each degree lands
     * on, must be identical.
     */
    @Test fun builtInScalaTuningsLandOnTheSameNotesAndBends() {
        for (case in SCL) {
            val tuning = Scl.parse(case.text, case.file)
            assertEquals(case.name, tuning.name, case.file)
            assertEquals(case.cents.size, tuning.cents.size, case.file)
            case.cents.forEachIndexed { i, bits ->
                val expected = Double.fromBits(bits)
                assertTrue(abs(tuning.cents[i] - expected) < 1e-9, "${case.file} degree $i: ${tuning.cents[i]} vs $expected")
            }
            val landed = TuningMap(tuning).pitches.map { it.degree * 1000000 + it.note * 100 + it.detune }
            assertEquals(case.pitches.toList(), landed, case.file)
        }
    }

    @Test fun theExampleProjectExportsTheSameUge() {
        val uge = UgeExporter.export(ProjectCodec.decode(THOR_GROOVE))
        assertEquals(77994, uge.size)
        assertEquals(8755939705024339933L, fnv1a(uge))
        val demo = UgeExporter.export(Songs.demo())
        assertEquals(77994, demo.size)
        assertEquals(8755939705024339933L, fnv1a(demo))
    }

    private fun fnv1a(bytes: ByteArray): Long {
        var h = -0x340d631b7bdddcdbL
        for (b in bytes) { h = h xor (b.toLong() and 0xFF); h *= 0x100000001b3L }
        return h
    }

